#!/usr/bin/env python3
import random

def main():
    random.seed(0)
    target = random.randint(1, 100)
    guess = None
    print("Guess a number between 1 and 100:")
    while guess != target:
        try:
            guess = int(input())
        except EOFError:
            break
        if guess < target:
            print("Higher!")
        elif guess > target:
            print("Lower!")
        else:
            print("Correct! You win!")

if __name__ == "__main__":
    main()

